package vn.svframe.lively.admin;
import net.minecraft.util.math.BlockPos;import java.util.*;import java.util.concurrent.*;public final class SelectionService{public record Point(String world,BlockPos pos){}private static final ConcurrentHashMap<UUID,Point>FIRST=new ConcurrentHashMap<>(),SECOND=new ConcurrentHashMap<>();private SelectionService(){}public static void set(UUID player,boolean first,String world,BlockPos pos){(first?FIRST:SECOND).put(player,new Point(world,pos.toImmutable()));}public static Optional<Point>first(UUID p){return Optional.ofNullable(FIRST.get(p));}public static Optional<Point>second(UUID p){return Optional.ofNullable(SECOND.get(p));}public static void clear(UUID p){FIRST.remove(p);SECOND.remove(p);}}
